def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    workforce_before_restructuring = v1 / (v2 / 100)

    return {
        "value": workforce_before_restructuring,
        "trace": {
            "employees_terminated": v1,
            "termination_percentage": v2,
            "termination_fraction": v2 / 100,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "employees"
            }
        }
    }
